from vastai import Worker, WorkerConfig, HandlerConfig, BenchmarkConfig, LogActionConfig

MODEL_SERVER_URL="http://127.0.0.1"
MODEL_SERVER_PORT=18000
MODEL_LOG_FILE="/var/log/truecolorize/model.log"
BENCHMARK_IMAGE=""

def benchmark_payload():
    return {
        "image_base64": BENCHMARK_IMAGE,
        "model": "artistic",
        "quality": "fast",
        "strength": 0.8,
        "filter": "natural"
    }

cfg=WorkerConfig(
    model_server_url=MODEL_SERVER_URL,
    model_server_port=MODEL_SERVER_PORT,
    model_log_file=MODEL_LOG_FILE,
    handlers=[HandlerConfig(
        route="/colorize",
        allow_parallel_requests=False,
        max_queue_time=180.0,
        workload_calculator=lambda payload: 100.0,
        benchmark_config=BenchmarkConfig(generator=benchmark_payload,runs=1,concurrency=1)
    )],
    log_action_config=LogActionConfig(
        on_load=["TRUECOLORIZE_MODEL_READY"],
        on_error=["TRUECOLORIZE_ERROR","Traceback (most recent call last):"],
        on_info=["TRUECOLORIZE_INFO"]
    )
)
Worker(cfg).run()
